function countVowels(name) {
  var count = 0;
  // iterate over each character
  for (var i = 0; i < name.length; i++) {
    var ch = name[i].toLowerCase();
    if (ch === 'a' || ch === 'e' || ch === 'i' || ch === 'o' || ch === 'u') {
      count++;
    }
  }
  return count;
}

console.log(countVowels("Ayesha"));

